export function buildPage10BillingShippingHtml(data: QuotationData): string {
  const clientName = data.clientName || 'Mr. Rathish Rajakumar';
  const offerNo = data.offerNo || 'AE/QTN/ AE-261026-131';
  const offerDate = data.offerDate || '26/10/2026';
  const projectCity = data.projectCity || 'Chennai';
  const model = data.model || 'AE 03 Gearless Belt Home series EV';
  const clientEmail = data.clientEmail || 'info@rathishelevators.com';
  const customerPhone = data.customerPhone || '+91 98200 11101';

  const hasGst = Boolean(data.hasGst && data.gstNumber && data.gstNumber.trim() !== '');
  const gstStatus = hasGst
    ? 'Registered Taxable Person (GSTIN)'
    : 'Unregistered Consumer / Residential Project (B2C)';
  const gstNumber = hasGst ? data.gstNumber : 'Not Applicable (Non-GST)';

  const billingAddress =
    data.billingAddress || data.siteAddress || 'No. 42, 2nd Avenue, Anna Nagar East, Chennai - 600102, Tamil Nadu';
  const shippingAddress =
    (data.sameAsBilling !== false
      ? data.billingAddress || data.siteAddress
      : data.shippingAddress || data.siteAddress) || billingAddress;

  // Use base template of Page 10 (pageIdx 9) from EXACT_PDF_PAGES_RAW
  let html = EXACT_PDF_PAGES_RAW[9] || '';
  if (!html) return '';

  // Dynamic replacements for Page 10
  html = html.replace('Mr. Rathish Rajakumar', clientName);
  html = html.replace('AE/QTN/ AE-261026-131', offerNo);
  html = html.replace(/Date:\s*26\/10\/2026/g, `Date: ${offerDate}`);
  html = html.replace('>Chennai<', `>${projectCity}<`);
  html = html.replace('info@rathishelevators.com', clientEmail);
  html = html.replace('+91 98200 11101', customerPhone);
  html = html.replace('AE 03 Gearless Belt Home series EV', model);

  html = html.replace(
    'Unregistered Consumer / Residential Project (B2C)',
    gstStatus
  );
  html = html.replace(
    'Not Applicable (Non-GST)',
    gstNumber || 'Not Applicable (Non-GST)'
  );

  html = html.replace(
    'No. 42, 2nd Avenue, Anna Nagar East, Chennai - 600102, Tamil Nadu',
    billingAddress
  );
  html = html.replace(
    'No. 42, 2nd Avenue, Anna Nagar East, Chennai - 600102, Tamil Nadu',
    shippingAddress
  );

  return html;
}

export function renderExactPdfPage(pageIdx: number, data: QuotationData): string {
  if (pageIdx === 9) {
    let html = buildPage10BillingShippingHtml(data);
    html = html.replace(`id="p9"`, `id="p9" data-page="10" style="width:793.28px;height:1122.72px;position:relative;display:block;overflow:hidden;background:#ffffff;"`);
    return html;
  }

  let html = EXACT_PDF_PAGES_RAW[pageIdx] || '';
  if (!html) return '';

  const formatINR = (val: number) => Number(val || 0).toLocaleString('en-IN');

  if (pageIdx === 0) {
    // Page 1: Cover
    html = html.replace('CLIENT NAME: Mr. Rathish Rajakumar', 'CLIENT NAME: ' + (data.clientName || 'Mr. Rathish Rajakumar'));
    html = html.replace('Project City:  Chennai', 'Project City:  ' + (data.projectCity || 'Chennai'));
    html = html.replace(/MODEL : [^\n<]+/i, 'MODEL : ' + (data.model || 'AE 03 Gearless Belt Home series EV') + ' ');
    html = html.replace('Offer No: AE/QTN/ AE-241026-131', 'Offer No: ' + (data.offerNo || 'AE/QTN/ AE-241026-131'));
    // Ensure Client Name, Project City, and Model match Project Proposal font color (#0f4b31)
    html = html.replace(/class="t c1"/g, 'class="t c1" style="color:#0f4b31 !important;"');
    html = html.replace(/<img class="im"[^>]*style="[^"]*714\.6[^"]*"[^>]*>/g, '');
  } else if (pageIdx === 1) {
    // Page 2: Letter
    html = html.replace('AE/QTN/AE- 261026-131', data.offerNo || 'AE/QTN/AE- 261026-131');
    // Prioritize client full name typed in form, or custom salutation
    const rawClientName = data.clientName?.trim() || (data.salutation ? data.salutation.replace(/^Dear\s*/i, '').trim() : '');
    const salutationName = (rawClientName ? rawClientName.replace(/^Dear\s*/i, '').trim() : '') || 'Mr. Rathish Rajakumar';
    html = html.replace('Mr. Rathish Rajakumar ', salutationName + ' ');
    html = html.replace('Mr. Rathish Rajakumar', salutationName);
    // Ensure customer name font color matches Dear's font color (#0e4b31)
    html = html.replace(
      '<div class="t c9" style="z-index:1263;transform:matrix(1,0,0,1,94.46,200.44)">',
      '<div class="t c8" style="z-index:1263;transform:matrix(1,0,0,1,94.46,200.44);color:#0e4b31;">'
    );
    if (data.subject) {
      html = html.replace('Sub: Supply, Install, test and commission of one Belt Type Home Elevator EV ', 'Sub: ' + data.subject + ' ');
    }
    if (data.visionText) {
      html = html.replace('Elevating possibilities and building lasting bonds — one lift at a time', data.visionText);
    }
  } else if (pageIdx === 2) {
    // Page 3: Civil & Cabin
    html = html.replace('AE-261026-131', data.offerNo ? data.offerNo.replace(/^AE\/QTN\/\s*/i, '') : 'AE-261026-131');
    if (data.model) {
      html = html.replace(/<div class="t c9" style="z-index:791;transform:matrix\(1,0,0,1,310\.59,191\.55\)">[\s\S]*?<\/div>/, `<div class="t c9" style="z-index:791;transform:matrix(1,0,0,1,310.59,191.55)">${data.model}</div>`);
      html = html.replace(/<div class="t c17" style="z-index:729;transform:matrix\(1,0,0,1,346\.53,364\.86\)">[\s\S]*?<\/div>/, `<div class="t c17" style="z-index:729;transform:matrix(1,0,0,1,346.53,364.86)">${data.model}</div>`);
      html = html.replace('AE 03 Gearless Belt Home', data.model);
      html = html.replace('AE 03 Home Elevator EV', data.model);
    }
    if (data.hoistWayShaftSize) html = html.replace('1450mm X 1800mm', data.hoistWayShaftSize);
    if (data.pitDepth) {
      html = html.replace(/<div class="t c16" style="z-index:142;transform:matrix\(1,0,0,1,489\.12,528\.02\)">[\s\S]*?<\/div>/, `<div class="t c16" style="z-index:142;transform:matrix(1,0,0,1,489.12,528.02)">${data.pitDepth}</div>`);
      html = html.replace('250mm', data.pitDepth);
    }
    if (data.minFloorHeight) html = html.replace('3000mm', data.minFloorHeight);
    if (data.finalStop) html = html.replace('3300mm', data.finalStop);
    if (data.lockableStorageRoom) {
      html = html.replace(/<div class="t c16" style="z-index:231;transform:matrix\(1,0,0,1,419\.84,687\.22\)">[\s\S]*?<\/div>/, `<div class="t c16" style="z-index:231;transform:matrix(1,0,0,1,419.84,687.22)">${data.lockableStorageRoom}</div>`);
      html = html.replace(/To be located in the (top|ground) floor/i, data.lockableStorageRoom);
    }
    if (data.cabinWalls) {
      html = html.replace(/<div class="t c15" style="z-index:159;transform:matrix\(1,0,0,1,490\.24,806\.2\)">[\s\S]*?<\/div>/, `<div class="t c15" style="z-index:159;transform:matrix(1,0,0,1,490.24,806.2)">${data.cabinWalls}</div>`);
      html = html.replace('SS Cabin', data.cabinWalls);
    }
    if (data.cabinFloor) html = html.replace('Vinyl or Client’s own Flooring', data.cabinFloor);
    if (data.ceiling) html = html.replace('As per cabin design', data.ceiling);
    if (data.copAndLop) {
      html = html.replace(/<div class="t c15" style="z-index:137;transform:matrix\(1,0,0,1,492\.77,953\.27\)">[\s\S]*?<\/div>/, `<div class="t c15" style="z-index:137;transform:matrix(1,0,0,1,492.77,953.27)">${data.copAndLop}</div>`);
      html = html.replace('>Touch<', `>${data.copAndLop}<`);
    }
  } else if (pageIdx === 3) {
    // Page 4: Elevator & Door
    html = html.replace('AE/QTN/ AE-261026-131', data.offerNo || 'AE/QTN/ AE-261026-131');
    if (data.doorSpecifications) {
      html = html.replace(/<div class="t c15" style="z-index:210;transform:matrix\(1,0,0,1,333\.76,914\.39\)">[\s\S]*?<\/div>/, `<div class="t c15" style="z-index:210;transform:matrix(1,0,0,1,333.76,914.39)">${data.doorSpecifications}</div>`);
      html = html.replace(/Auto Telescopic\s*Doors - SS 304 Grade/i, data.doorSpecifications);
    }

    const isEv = Boolean(
      (data.model && /\bEV\b|home\s*EV|battery/i.test(data.model)) || (data.battery && data.battery.trim() !== '')
    );

    const ratedLoadVal = data.ratedLoad || 'Upto 5 Passengers /408 kgs ';
    const noOfStopsVal = data.noOfStops || 'G+2';
    const noOfOpeningsVal = data.noOfOpenings || '3 Openings';
    const floorNumberingVal = data.floorNumbering || 'G,1,2';
    const doorOpeningVal =
      data.doorOpening ||
      (['inline', 'adjacent', 'Opposite Side', 'inline and adjacent', 'Same Side'].includes(data.doorAccess)
        ? data.doorAccess
        : 'inline');
    const doorAccessVal =
      data.doorAccess &&
      !['inline', 'adjacent', 'Opposite Side', 'inline and adjacent', 'Same Side'].includes(data.doorAccess)
        ? data.doorAccess
        : 'G - ABCG, 1 - ABCG, 2 - ABCG, 3 - ABCG';
    const travelHeightVal = data.totalTravelHeight || '7000mm';
    const controllerVal = data.controller || 'Indian';
    const speedVal = data.speed || '.4 m/s';
    const machineVal = data.machine || 'Imported  Motor';
    const powerSupplyVal = data.powerSupply || 'Single phase 220V';
    const carSizeVal = data.carSize || 'TBC*';
    const batteryVal = data.battery || 'Lithium-ion';
    const clearOpeningVal = data.clearOpening || 'TBC*';
    const customerSpecificRequirementsVal = data.customerSpecificRequirements || 'Nil';

    const rowH = isEv ? '37.2px' : '39.85px';
    const fontSize = isEv ? '12px' : '12.5px';

    const batteryRowHtml = isEv ? `
<tr style="height:${rowH};border-bottom:1px solid #000000;">
<td style="width:175.25px;text-align:center;vertical-align:middle;border-right:1px solid #000000;font-family:'f1',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">Battery</td>
<td style="width:480.25px;text-align:center;vertical-align:middle;font-family:'f3',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">${batteryVal}</td>
</tr>` : '';

    const specTable = `<table style="position:absolute;left:58.25px;top:243.5px;width:655.5px;height:558px;border-collapse:collapse;background:#ffffff;z-index:50;border:1px solid #000000;box-sizing:border-box;">
<tbody>
<tr style="height:${rowH};border-bottom:1px solid #000000;">
<td style="width:175.25px;text-align:center;vertical-align:middle;border-right:1px solid #000000;font-family:'f1',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">Rated Load</td>
<td style="width:480.25px;text-align:center;vertical-align:middle;font-family:'f3',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">${ratedLoadVal}</td>
</tr>
<tr style="height:${rowH};border-bottom:1px solid #000000;">
<td style="width:175.25px;text-align:center;vertical-align:middle;border-right:1px solid #000000;font-family:'f1',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">No of Stops</td>
<td style="width:480.25px;text-align:center;vertical-align:middle;font-family:'f3',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">${noOfStopsVal}</td>
</tr>
<tr style="height:${rowH};border-bottom:1px solid #000000;">
<td style="width:175.25px;text-align:center;vertical-align:middle;border-right:1px solid #000000;font-family:'f1',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">No Of Openings</td>
<td style="width:480.25px;text-align:center;vertical-align:middle;font-family:'f3',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">${noOfOpeningsVal}</td>
</tr>
<tr style="height:${rowH};border-bottom:1px solid #000000;">
<td style="width:175.25px;text-align:center;vertical-align:middle;border-right:1px solid #000000;font-family:'f1',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">Floor Numbering</td>
<td style="width:480.25px;text-align:center;vertical-align:middle;font-family:'f3',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">${floorNumberingVal}</td>
</tr>
<tr style="height:${rowH};border-bottom:1px solid #000000;">
<td style="width:175.25px;text-align:center;vertical-align:middle;border-right:1px solid #000000;font-family:'f1',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">Door Opening</td>
<td style="width:480.25px;text-align:center;vertical-align:middle;font-family:'f3',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">${doorOpeningVal}</td>
</tr>
<tr style="height:${rowH};border-bottom:1px solid #000000;">
<td style="width:175.25px;text-align:center;vertical-align:middle;border-right:1px solid #000000;font-family:'f1',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">Door Access</td>
<td style="width:480.25px;text-align:center;vertical-align:middle;font-family:'f3',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">${doorAccessVal}</td>
</tr>
<tr style="height:${rowH};border-bottom:1px solid #000000;">
<td style="width:175.25px;text-align:center;vertical-align:middle;border-right:1px solid #000000;font-family:'f1',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">Total Travel Height</td>
<td style="width:480.25px;text-align:center;vertical-align:middle;font-family:'f3',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">${travelHeightVal}</td>
</tr>
<tr style="height:${rowH};border-bottom:1px solid #000000;">
<td style="width:175.25px;text-align:center;vertical-align:middle;border-right:1px solid #000000;font-family:'f1',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">Controller</td>
<td style="width:480.25px;text-align:center;vertical-align:middle;font-family:'f3',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">${controllerVal}</td>
</tr>
<tr style="height:${rowH};border-bottom:1px solid #000000;">
<td style="width:175.25px;text-align:center;vertical-align:middle;border-right:1px solid #000000;font-family:'f1',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">Speed</td>
<td style="width:480.25px;text-align:center;vertical-align:middle;font-family:'f3',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">${speedVal}</td>
</tr>
<tr style="height:${rowH};border-bottom:1px solid #000000;">
<td style="width:175.25px;text-align:center;vertical-align:middle;border-right:1px solid #000000;font-family:'f1',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">Machine</td>
<td style="width:480.25px;text-align:center;vertical-align:middle;font-family:'f3',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">${machineVal}</td>
</tr>
<tr style="height:${rowH};border-bottom:1px solid #000000;">
<td style="width:175.25px;text-align:center;vertical-align:middle;border-right:1px solid #000000;font-family:'f1',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">Power Supply</td>
<td style="width:480.25px;text-align:center;vertical-align:middle;font-family:'f3',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">${powerSupplyVal}</td>
</tr>
<tr style="height:${rowH};border-bottom:1px solid #000000;">
<td style="width:175.25px;text-align:center;vertical-align:middle;border-right:1px solid #000000;font-family:'f1',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">Car Size</td>
<td style="width:480.25px;text-align:center;vertical-align:middle;font-family:'f3',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">${carSizeVal}</td>
</tr>${batteryRowHtml}
<tr style="height:${rowH};border-bottom:1px solid #000000;">
<td style="width:175.25px;text-align:center;vertical-align:middle;border-right:1px solid #000000;font-family:'f1',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">Clear Opening</td>
<td style="width:480.25px;text-align:center;vertical-align:middle;font-family:'f3',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">${clearOpeningVal}</td>
</tr>
<tr style="height:${rowH};">
<td style="width:175.25px;text-align:center;vertical-align:middle;border-right:1px solid #000000;font-family:'f1',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">Customer Specific requirements</td>
<td style="width:480.25px;text-align:center;vertical-align:middle;font-family:'f3',sans-serif;font-size:${fontSize};color:#1a3f2e;padding:0;margin:0;">${customerSpecificRequirementsVal}</td>
</tr>
</tbody>
</table>`;

    const tableRegex = /<table style="position:absolute;left:58\.25px;top:243\.5px;[\s\S]*?<\/table>/;
    if (tableRegex.test(html)) {
      html = html.replace(tableRegex, specTable);
    }
  } else if (pageIdx === 4) {
    // Page 5: Shaft, Accessories, Terms
    html = html.replace('AE/QTN/AE-261026-131', data.offerNo || 'AE/QTN/AE-261026-131');
    const effectiveShaft = (data.shaftScope === 'Customer scope' || data.shaftType === 'Customer scope') ? 'Customer scope' : data.shaftType;
    if (effectiveShaft) {
      html = html.replace(/<div class="t c13" style="z-index:381;transform:matrix\(1,0,0,1,260\.73,213\.5\)">[\s\S]*?<\/div>/, `<div class="t c13" style="z-index:381;transform:matrix(1,0,0,1,260.73,213.5)">${effectiveShaft}</div>`);
      html = html.replace(/Shaft-Glass Shaft\s*/i, effectiveShaft);
    }
    // Elevator Price
    const gstRate = data.gstRate !== undefined ? data.gstRate : 18;
    const elvMRP = data.elevatorPrice ? 'Rs. ' + formatINR(data.elevatorPrice) + ' + ' + gstRate + '% GST' : '';
    const hasElvDiscount = Boolean(
      data.elevatorDiscountPrice &&
      Number(data.elevatorDiscountPrice) > 0 &&
      Number(data.elevatorDiscountPrice) !== Number(data.elevatorPrice)
    );

    if (hasElvDiscount && data.elevatorPrice) {
      const elvDiscText = 'Rs. ' + formatINR(Number(data.elevatorDiscountPrice)) + ' + ' + gstRate + '% GST';
      const elvReplacement = `<div class="t c21" style="position:absolute;left:320.51px;top:605px;line-height:13.5px;white-space:normal;z-index:825;"><div style="text-decoration:line-through;color:#718096;font-size:10px;">MRP: ${elvMRP}</div><div style="color:#0e4b31;font-weight:bold;font-size:12px;">Discount Price: ${elvDiscText}</div></div>`;
      const elvRegex = /<div class="t c21" style="z-index:825;transform:matrix\(1,0,0,1,320\.51,611\.2\)">[\s\S]*?<\/div>/;
      if (elvRegex.test(html)) {
        html = html.replace(elvRegex, elvReplacement);
      } else {
        html = html.replace('Rs. 16,00,,000 + 18% GST', `${elvDiscText} (MRP: ${elvMRP})`);
      }
    } else if (data.elevatorPrice) {
      html = html.replace('Rs. 16,00,,000 + 18% GST', elvMRP);
    }

    // Shaft Price
    const shaftMRP = data.shaftPrice ? 'Rs. ' + formatINR(data.shaftPrice) + ' + ' + gstRate + '% GST' : '';
    const hasShaftDiscount = Boolean(
      data.shaftDiscountPrice &&
      Number(data.shaftDiscountPrice) > 0 &&
      Number(data.shaftDiscountPrice) !== Number(data.shaftPrice)
    );

    if (hasShaftDiscount && data.shaftPrice) {
      const shaftDiscText = 'Rs. ' + formatINR(Number(data.shaftDiscountPrice)) + ' + ' + gstRate + '% GST';
      const shaftReplacement = `<div class="t c25" style="position:absolute;left:325.09px;top:649px;line-height:13.5px;white-space:normal;z-index:878;"><div style="text-decoration:line-through;color:#718096;font-size:10px;">MRP: ${shaftMRP}</div><div style="color:#0e4b31;font-weight:bold;font-size:12px;">Discount Price: ${shaftDiscText}</div></div>`;
      const shaftRegex = /<div class="t c25" style="z-index:878;transform:matrix\(1,0,0,1,325\.09,655\.24\)">[\s\S]*?<\/div>/;
      if (shaftRegex.test(html)) {
        html = html.replace(shaftRegex, shaftReplacement);
      } else {
        html = html.replace('Rs.4,00,000 + 18% GST', `${shaftDiscText} (MRP: ${shaftMRP})`);
      }
    } else if (data.shaftPrice) {
      html = html.replace('Rs.4,00,000 + 18% GST', shaftMRP);
    }
    const warrantyCellRegex = /<div class="t c26" style="z-index:907;transform:matrix\(1,0,0,1,252\.41,682\.01\)">[\s\S]*?years service\.<\/div>/;
    if (data.warranty && warrantyCellRegex.test(html)) {
      html = html.replace(warrantyCellRegex, `<div class="t c26" style="position:absolute;left:252.41px;top:682.01px;width:490px;white-space:normal;line-height:14.4px;font-family:'f6',sans-serif;font-size:12px;color:#1a3f2e;z-index:907;">${data.warranty}</div>`);
    } else if (data.warranty) {
      const customWarrantyRegex = /<div class="t c26" style="position:absolute;left:252\.41px;top:682\.01px;[\s\S]*?<\/div>/;
      if (customWarrantyRegex.test(html)) {
        html = html.replace(customWarrantyRegex, `<div class="t c26" style="position:absolute;left:252.41px;top:682.01px;width:490px;white-space:normal;line-height:14.4px;font-family:'f6',sans-serif;font-size:12px;color:#1a3f2e;z-index:907;">${data.warranty}</div>`);
      } else {
        html = html.replace('Lifetime- MOTOR WARRANTY, 5 years - manufacturing warranty + 1 Years', data.warranty);
      }
    }
    if (data.deliveryTime) {
      html = html.replace(/\b\d+\s*days post confirmation on drawings and finishes\./, data.deliveryTime);
    }
    if (data.paymentTerms?.booking) {
      html = html.replace('. Booking – 30%', data.paymentTerms.booking.replace(/^[0-9.]+\s*/, ''));
    }
  } else if (pageIdx === 5) {
    // Page 6: Dispatch and Installation, Warranty & Maintenance
    const deliveryDays = data.deliveryDays || parseDeliveryDays(data.deliveryTime) || 120;
    html = html.replace(/(Delivery of material shall be )\d+( working days)/, `$1${deliveryDays}$2`);

    const page6Warranty = buildPage6WarrantyParagraph(data);
    const warrantyRegex = /<div class="t c23" style="position:absolute;left:33\.41px;top:346\.51px;[\s\S]*?Applicable after \d+ years\.<\/div>/;
    if (warrantyRegex.test(html)) {
      html = html.replace(warrantyRegex, page6Warranty);
    }
  } else if (pageIdx === 8) {
    // Page 9: Signatures
    const clientName = data.clientSignatoryName || data.clientName;
    if (clientName) {
      html = html.replace('Name:</div>', 'Name: ' + clientName + '</div>');
    }
    const alphaName = data.alphaSignatoryName || data.representativeName;
    if (alphaName) {
      // second occurrence of Name:
      let firstIdx = html.indexOf('Name:');
      if (firstIdx !== -1) {
        let secondIdx = html.indexOf('Name:', firstIdx + 5);
        if (secondIdx !== -1) {
          html = html.substring(0, secondIdx) + 'Name: ' + alphaName + html.substring(secondIdx + 5);
        }
      }
    }
  } else if (pageIdx === 10) {
    // Page 11: Back Cover - change green elements to black
    html = html.replace(/class="t c35"/g, 'class="t c35" style="color:#000000 !important;"');
    html = html.replace(/class="t c37"/g, 'class="t c37" style="color:#000000 !important;"');
  }

  // Ensure dual id for both pdf2html styles (#p0..#p9) and html2canvas print (#quotation-page-1..#quotation-page-10)
  // Pages 3 to 8 (pageIdx 2 to 7): Add Client Signature block for sign process (Page 9 has main acceptance block)
  if (pageIdx >= 2 && pageIdx <= 7 && !html.includes('client-signature-box')) {
    const clientSignBlock = `<div class="client-signature-box" style="position:absolute;right:45px;bottom:92px;z-index:9000;text-align:center;pointer-events:auto;"><div style="width:150px;border-bottom:1.5px solid #0e4b31;margin-bottom:4px;"></div><span style="font-family:'f2',sans-serif;font-size:10px;font-weight:bold;color:#0e4b31;letter-spacing:0.5px;text-transform:uppercase;">Client Signature</span></div>`;
    const lastCloseDiv = html.lastIndexOf('</div>');
    if (lastCloseDiv !== -1) {
      html = html.substring(0, lastCloseDiv) + clientSignBlock + html.substring(lastCloseDiv);
    }
  }

  // Sanitize and align all paragraphs for Pages 6 to 9 (and full document)
  html = sanitizeProposalParagraphs(html, pageIdx + 1, data);

  html = html.replace(
    `id="p${pageIdx}"`,
    `id="p${pageIdx}" data-page="${pageIdx + 1}" style="width:793.28px;height:1122.72px;position:relative;display:block;overflow:hidden;background:#ffffff;"`
  );

  return html;
}
